package logfan

import (
    "context"
    "log/slog"
    "sync"
)

// Ring is an in-memory ring-buffer slog handler.
type Ring struct {
    mu       sync.RWMutex
    capacity int
    records  []slog.Record
    start    int // index of oldest record
    count    int // number of records in buffer
}

// NewRing creates a ring-buffer slog handler.
func NewRing(capacity int) (*Ring, error) {
    if capacity <= 0 {
        return nil, fmt.Errorf("logfan: capacity must be positive, got %d", capacity)
    }
    return &Ring{
        capacity: capacity,
        records:  make([]slog.Record, capacity),
    }, nil
}

func (r *Ring) Enabled(ctx context.Context, level slog.Level) bool {
    return true
}

func (r *Ring) Handle(ctx context.Context, rec slog.Record) error {
    r.mu.Lock()
    defer r.mu.Unlock()

    if r.count < r.capacity {
        r.records[(r.start+r.count)%r.capacity] = rec.Clone()
        r.count++
    } else {
        r.records[r.start] = rec.Clone()
        r.start = (r.start + 1) % r.capacity
    }
    return nil
}

func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
    // Return a handler that chains to this ring
    return &ringHandler{r: r, attrs: attrs}
}

func (r *Ring) WithGroup(name string) slog.Handler {
    return &ringHandler{r: r, group: name}
}

// Records returns buffered records, oldest first.
func (r *Ring) Records() []slog.Record {
    r.mu.RLock()
    defer r.mu.RUnlock()

    result := make([]slog.Record, r.count)
    for i := 0; i < r.count; i++ {
        result[i] = r.records[(r.start+i)%r.capacity]
    }
    return result
}

// ringHandler is a wrapper that adds attrs/groups before passing to the Ring.
type ringHandler struct {
    r     *Ring
    attrs []slog.Attr
    group string
}

func (h *ringHandler) Enabled(ctx context.Context, level slog.Level) bool {
    return true
}

func (h *ringHandler) Handle(ctx context.Context, rec slog.Record) error {
    // Add attrs to the record before storing
    if len(h.attrs) > 0 {
        rec.AddAttrs(h.attrs...)
    }
    // Group handling...
