package logfan

import (
	"context"
	"fmt"
	"log/slog"
	"sync"
)

// Ring is an in-memory ring-buffer slog handler that keeps the most recent
// capacity records.
type Ring struct {
	mu       sync.RWMutex
	capacity int
	buf      []slog.Record
	start    int // index of oldest record
	count    int // number of records currently stored
}

// NewRing creates a ring-buffer slog handler.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("logfan: capacity must be positive, got %d", capacity)
	}
	return &Ring{
		capacity: capacity,
		buf:      make([]slog.Record, capacity),
	}, nil
}

// Enabled reports whether the handler handles records at the given level.
func (r *Ring) Enabled(context.Context, slog.Level) bool { return true }

// Handle handles the Record. All levels are accepted.
func (r *Ring) Handle(_ context.Context, rec slog.Record) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	rec = rec.Clone()
	if r.count < r.capacity {
		r.buf[(r.start+r.count)%r.capacity] = rec
		r.count++
	} else {
		r.buf[r.start] = rec
		r.start = (r.start + 1) % r.capacity
	}
	return nil
}

// WithAttrs returns a new handler whose records include the given attributes
// in addition to the receiver's own attributes.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	return &ringSubHandler{r: r, preAttrs: attrs}
}

// WithGroup returns a new handler whose records are grouped under the given
// name.
func (r *Ring) WithGroup(name string) slog.Handler {
	return &ringSubHandler{r: r, groups: []string{name}}
}

// Records returns the buffered records, oldest first. The returned slice is a
// copy; mutating it does not affect the ring.
func (r *Ring) Records() []slog.Record {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]slog.Record, r.count)
	for i := 0; i < r.count; i++ {
		out[i] = r.buf[(r.start+i)%r.capacity]
	}
	return out
}

// ringSubHandler wraps a Ring with pre-attrs and open groups, producing a
// slog.Handler that chains to the Ring when a record is handled.
type ringSubHandler struct {
	r        *Ring
	preAttrs []slog.Attr
	groups   []string
}

func (h *ringSubHandler) Enabled(context.Context, slog.Level) bool { return true }

func (h *ringSubHandler) Handle(ctx context.Context, rec slog.Record) error {
	resolved := resolveAttrs(h.groups, h.preAttrs)
	if len(resolved) > 0 {
		rec.AddAttrs(resolved...)
	}
	return h.r.Handle(ctx, rec)
}

func (h *ringSubHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	// Merge new attrs into the current group context.
	newPreAttrs := h.preAttrs
	if len(h.groups) > 0 {
		wrapped := attrs
		for i := len(h.groups) - 1; i >= 0; i-- {
			wrapped = []slog.Attr{slog.Group(h.groups[i], wrapped...)}
		}
		newPreAttrs = append(newPreAttrs, wrapped...)
		return &ringSubHandler{r: h.r, preAttrs: newPreAttrs}
	}
	newPreAttrs = append(append([]slog.Attr{}, h.preAttrs...), attrs...)
	return &ringSubHandler{r: h.r, preAttrs: newPreAttrs}
}

func (h *ringSubHandler) WithGroup(name string) slog.Handler {
	return &ringSubHandler{
		r:        h.r,
		preAttrs: h.preAttrs,
		groups:   append(append([]string{}, h.groups...), name),
	}
}

// resolveAttrs wraps pre-attrs with the open group names so that the result
// reflects slog's group nesting rules.
func resolveAttrs(groups []string, attrs []slog.Attr) []slog.Attr {
	if len(groups) == 0 {
		return attrs
	}
	// Walk groups from innermost outward so that the outermost group
	// appears first in the result.
	result := attrs
	for i := len(groups) - 1; i >= 0; i-- {
		result = []slog.Attr{slog.Group(groups[i], result...)}
	}
	return result
}

package logfan

import (
	"context"
	"fmt"
	"log/slog"
)

// New builds a logger that delivers every record to ALL given handlers.
// It returns an error when called with no handlers.
func New(handlers ...slog.Handler) (*slog.Logger, error) {
	if len(handlers) == 0 {
		return nil, fmt.Errorf("logfan: at least one handler is required")
	}
	return slog.New(&fanoutHandler{handlers: handlers}), nil
}

// fanoutHandler delivers every record to all wrapped handlers.
type fanoutHandler struct {
	handlers []slog.Handler
}

func (h *fanoutHandler) Enabled(ctx context.Context, level slog.Level) bool {
	for _, handler := range h.handlers {
		if handler.Enabled(ctx, level) {
			return true
		}
	}
	return false
}

func (h *fanoutHandler) Handle(ctx context.Context, rec slog.Record) error {
	for _, handler := range h.handlers {
		if err := handler.Handle(ctx, rec); err != nil {
			return err
		}
	}
	return nil
}

func (h *fanoutHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	handlers := make([]slog.Handler, len(h.handlers))
	for i, handler := range h.handlers {
		handlers[i] = handler.WithAttrs(attrs)
	}
	return &fanoutHandler{handlers: handlers}
}

func (h *fanoutHandler) WithGroup(name string) slog.Handler {
	handlers := make([]slog.Handler, len(h.handlers))
	for i, handler := range h.handlers {
		handlers[i] = handler.WithGroup(name)
	}
	return &fanoutHandler{handlers: handlers}
}

package logfan

import (
	"context"
	"log/slog"
	"sync"
	"testing"
)

// ---------------------------------------------------------------------------
// Ring tests
// ---------------------------------------------------------------------------

func TestNewRing_InvalidCapacity(t *testing.T) {
	tests := []struct {
		name string
		c    int
	}{
		{"zero", 0},
		{"negative", -1},
		{"negative large", -42},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := NewRing(tt.c)
			if err == nil {
				t.Fatal("expected error for capacity", tt.c)
			}
		})
	}
}

func TestNewRing_ValidCapacity(t *testing.T) {
	r, err := NewRing(5)
	if err != nil {
		t.Fatal("unexpected error:", err)
	}
	if r == nil {
		t.Fatal("expected non-nil Ring")
	}
	recs := r.Records()
	if len(recs) != 0 {
		t.Fatalf("expected empty records, got %d", len(recs))
	}
}

func TestRing_StoreAndRetrieve(t *testing.T) {
	r, err := NewRing(3)
	if err != nil {
		t.Fatal(err)
	}
	log := slog.New(r)
	log.Info("first")
	log.Warn("second")
	log.Error("third")

	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("expected 3 records, got %d", len(recs))
	}
	// Check order: oldest first
	if recs[0].Message != "first" {
		t.Errorf("expected msg[0]=first, got %q", recs[0].Message)
	}
	if recs[1].Message != "second" {
		t.Errorf("expected msg[1]=second, got %q", recs[1].Message)
	}
	if recs[2].Message != "third" {
		t.Errorf("expected msg[2]=third, got %q", recs[2].Message)
	}
	// Check levels
	if recs[0].Level != slog.LevelInfo {
		t.Errorf("expected level info, got %v", recs[0].Level)
	}
	if recs[2].Level != slog.LevelError {
		t.Errorf("expected level error, got %v", recs[2].Level)
	}
}

func TestRing_Eviction(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}
	log := slog.New(r)
	log.Info("keep1")
	log.Info("keep2")
	log.Info("evicted")

	recs := r.Records()
	if len(recs) != 2 {
		t.Fatalf("expected 2 records, got %d", len(recs))
	}
	if recs[0].Message != "keep1" {
		t.Errorf("expected msg[0]=keep1, got %q", recs[0].Message)
	}
	if recs[1].Message != "keep2" {
		t.Errorf("expected msg[1]=keep2, got %q", recs[1].Message)
	}
}

func TestRing_EvictionOverwriteOldest(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}
	log := slog.New(r)
	log.Info("a")
	log.Info("b")
	log.Info("c") // evicts "a"
	log.Info("d") // evicts "b"

	recs := r.Records()
	if len(recs) != 2 {
		t.Fatalf("expected 2 records, got %d", len(recs))
	}
	if recs[0].Message != "c" {
		t.Errorf("expected msg[0]=c, got %q", recs[0].Message)
	}
	if recs[1].Message != "d" {
		t.Errorf("expected msg[1]=d, got %q", recs[1].Message)
	}
}

func TestRing_RecordsCopy(t *testing.T) {
	r, err := NewRing(3)
	if err != nil {
		t.Fatal(err)
	}
	log := slog.New(r)
	log.Info("msg")

	recs := r.Records()
	// Mutate the returned slice
