	if err != nil {
		t.Fatal(err)
	}
	log.Info("a", slog.Int("n", 1))
	log.Warn("b")

	check := func(name string, recs []slog.Record) {
		if len(recs) != 2 {
			t.Fatalf("%s: expected 2 records, got %d", name, len(recs))
		}
		if recs[0].Message != "a" || recs[1].Message != "b" {
			t.Errorf("%s: messages mismatch", name)
		}
	}
	check("r1", r1.Records())
	check("r2", r2.Records())
}

